        return;

    inArgs->msg = msg;
    inArgs->msgSz = msg_sz;
    sem_post(&sem_in);
    sem_wait(&sem_out);

    *respMsg = outArgs->respMsg;
    *respMsgSz = outArgs->respMsgSz;

